#include <iostream>
#include <vector>

std::vector<int> running_sum(const std::vector<int>& v) {
    std::vector<int> out;
    out.reserve(v.size());
    int total = 0;
    for (int x : v) {
        total += x;
        out.push_back(total);
    }
    return out;
}

int main() {
    for (int x : running_sum({1, 2, 3, 4})) std::cout << x << ' ';
    std::cout << '\n';
}
```

