```cpp
#include <iostream>
#include <vector>

std::vector<double> moving_average(const std::vector<double>& xs, std::size_t k) {
    std::vector<double> out;
    if (k == 0 || k > xs.size()) return out;
    out.reserve(xs.size() - k + 1);
    double s = 0.0;
    for (std::size_t i = 0; i < k; ++i) s += xs[i];
    out.push_back(s / k);
    for (std::size_t i = k; i < xs.size(); ++i) {
        s += xs[i] - xs[i - k];
        out.push_back(s / k);
    }
    return out;
}

int main() {
    for (double m : moving_average({1, 2, 3, 4, 5}, 2)) std::cout << m << ' ';
    std::cout << '\n';
}
```

This is exactly the smoothing filter you used for noisy ultrasonic readings in week 10, now as a reusable function.

