```cpp
#include <iostream>
#include <map>
#include <sstream>
#include <string>

std::map<std::string, int> word_count(const std::string& text) {
    std::map<std::string, int> counts;
    std::istringstream in(text);
    for (std::string w; in >> w; ) ++counts[w];
    return counts;
}

int main() {
    for (const auto& [w, n] : word_count("to be or not to be")) std::cout << w << ' ' << n << '\n';
}
```

