#include <iostream>
#include <unordered_map>
#include <utility>
#include <vector>

std::pair<int, int> two_sum(const std::vector<int>& nums, int target) {
    std::unordered_map<int, int> idx;   // value -> index where we saw it
    for (int j = 0; j < static_cast<int>(nums.size()); ++j) {
        if (auto it = idx.find(target - nums[j]); it != idx.end())
            return {it->second, j};
        idx[nums[j]] = j;   // record after the lookup, so an element can't pair with itself
    }
    return {-1, -1};
}

int main() {
    auto [i, j] = two_sum({2, 7, 11, 15}, 9);
    std::cout << i << ' ' << j << '\n';
}
