std::map<std::string, double> average_by_student(const std::vector<std::pair<std::string, int>>& rows) {
    std::map<std::string, std::pair<int, int>> acc;   // name -> (sum, count)
    for (const auto& [name, score] : rows) {
        auto& [sum, count] = acc[name];   // [] is right here: we want to create missing entries
        sum += score;
        ++count;
    }
    std::map<std::string, double> out;
    for (const auto& [name, sc] : acc) out[name] = static_cast<double>(sc.first) / sc.second;
    return out;
}

int main() {
    for (const auto& [n, avg] : average_by_student({{"ana", 80}, {"bek", 60}, {"ana", 90}}))
        std::cout << n << ' ' << avg << '\n';
}
