struct Median3Filter {
    long buf[3] = {0, 0, 0};
    int i = 0, n = 0;

    long push(long x) {
        buf[i] = x;
        i = (i + 1) % 3;
        if (n < 3) ++n;
        long a = buf[0], b = n > 1 ? buf[1] : x, c = n > 2 ? buf[2] : x;
        return median3(a, b, c);
    }
};

