```cpp
#include <iostream>

enum class State { Drive, Backup, Turn };

struct Command {
    int left;
    int right;
};

struct Car {
    State state = State::Drive;
    unsigned long stateStart = 0;

    static constexpr long NEAR_CM = 20, CLEAR_CM = 35;
    static constexpr unsigned long BACKUP_MS = 400, TURN_MS = 350;

    void enter(State s, unsigned long now) {
        state = s;
        stateStart = now;
    }

    Command update(unsigned long now, long cm) {
        unsigned long elapsed = now - stateStart;
        switch (state) {
            case State::Drive:
                if (cm < NEAR_CM) enter(State::Backup, now);
                break;
            case State::Backup:
                if (elapsed >= BACKUP_MS) enter(State::Turn, now);
                break;
            case State::Turn:
                if (elapsed >= TURN_MS && cm > CLEAR_CM) enter(State::Drive, now);
                break;
        }
        switch (state) {
            case State::Drive:  return {200, 200};
            case State::Backup: return {-180, -180};
            case State::Turn:   return {-170, 170};
        }
        return {0, 0};
    }
};

int main() {
    Car car;
    struct Step { unsigned long t; long cm; };
    for (Step s : {Step{0, 100}, Step{10, 15}, Step{300, 15}, Step{411, 15}, Step{900, 30}, Step{900, 40}}) {
        Command c = car.update(s.t, s.cm);
        std::cout << s.t << "ms " << s.cm << "cm -> " << c.left << ',' << c.right << '\n';
    }
}
```

Note that BACKUP ignores the sensor entirely and TURN needs both conditions. That's a design choice worth defending in the README: a car that leaves TURN on time alone can turn straight into the same wall.

