#include <map>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

std::vector<std::string> top_k_words(const std::string& text, std::size_t k) {
    std::map<std::string, int> counts;
    std::istringstream in(text);
    for (std::string w; in >> w; ) ++counts[w];

    std::vector<std::pair<std::string, int>> items(counts.begin(), counts.end());
    std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });

    std::vector<std::string> out;
    for (std::size_t i = 0; i < std::min(k, items.size()); ++i) out.push_back(items[i].first);
    return out;
}

int main() {
    for (const auto& w : top_k_words("b a c a b a", 2)) std::cout << w << ' ';
    std::cout << '\n';
}
```

`std::partial_sort` would sort only the first k, O(n log k); worth knowing, not needed here.

